// The language (engine) is identical everywhere; host APIs (runtime) differ.
console.log("Math.max(1, 5) =", Math.max(1, 5));           // engine built-in
console.log("JSON:", JSON.stringify({ ok: true }));         // engine built-in

// typeof never throws on an undeclared name, so it is safe for detection
const hasWindow = typeof window !== "undefined";
const hasNode = typeof process !== "undefined" && !!(process.versions && process.versions.node);
console.log("window defined?", hasWindow);
console.log("Node's process defined?", hasNode);

// Reading an undeclared host global directly throws
try {
  document.title;
} catch (e) {
  console.log("reading document ->", e.name);
}

// setTimeout comes from the host, not from the ECMAScript spec
console.log("typeof setTimeout:", typeof setTimeout);
const host = hasWindow ? "browser" : hasNode ? "node" : "other";
console.log("running in:", host);

// var is function-scoped, let/const are block-scoped
function demo() {
  if (true) {
    var a = 1;
    let b = 2;
    const c = 3;
  }
  console.log("var leaks out of the block:", a);
  console.log("let is gone outside:", typeof b, "| const:", typeof c);
}
demo();

// Hoisting: var is undefined early, let/const hit the TDZ
console.log("v before declaration:", v);
var v = 10;
try {
  console.log(l);
} catch (e) {
  console.log("l before declaration ->", e.name);
}
let l = 20;

// const forbids reassignment, but not mutation
const obj = { n: 1 };
obj.n = 2;
console.log("mutated const object:", obj);
try {
  obj = {};
} catch (e) {
  console.log("reassign const ->", e.name);
}

// Eight types: seven primitives plus object
const samples = ["hi", 42, 10n, true, undefined, null, Symbol("s"), {}, [], function () {}];
for (const v of samples) {
  console.log(String(typeof v).padEnd(10), "<-", typeof v === "symbol" ? "Symbol(s)" : String(v).slice(0, 20));
}

// Quirks: typeof null is "object"; functions report "function"
console.log("typeof null:", typeof null);

// Reliable array check
console.log("Array.isArray([]):", Array.isArray([]), "| typeof []:", typeof []);

// Primitives compare by value, objects by reference
console.log('"a" === "a":', "a" === "a");
console.log("{} === {}:", {} === {});
const o = {};
console.log("o === o:", o === o);

// Primitives are immutable
let s = "cat";
s[0] = "b"; // silently ignored in sloppy mode
console.log("after s[0]='b':", s);

// undefined: nothing was assigned. null: deliberately empty.
let x;
const user = { name: "Ana", nickname: null };
function f(a) { return a; }
console.log("uninitialised x:", x);
console.log("missing property:", user.age);
console.log("missing argument:", f());
console.log("explicit null:", user.nickname);

console.log("null == undefined:", null == undefined);
console.log("null === undefined:", null === undefined);
console.log("typeof undefined / null:", typeof undefined, "/", typeof null);
console.log("Number(null) / Number(undefined):", Number(null), "/", Number(undefined));

// JSON keeps null but drops undefined properties
console.log("JSON:", JSON.stringify({ a: null, b: undefined, c: 1 }));

// Default parameters only trigger for undefined, not null
function greet(name = "guest") { return "hello " + name; }
console.log(greet(undefined), "|", greet(null));

// ?? treats both the same
console.log(null ?? "fallback", "|", undefined ?? "fallback", "|", 0 ?? "fallback");

// Loose (==) coerces; strict (===) does not
const pairs = [
  [1, "1"], [0, ""], [null, 0], [null, undefined],
  [[], false], [NaN, NaN], ["0", false], [[1, 2], "1,2"],
];
for (const [a, b] of pairs) {
  console.log(
    JSON.stringify(a), "vs", JSON.stringify(b),
    " ==:", String(a == b).padEnd(5),
    " ===:", a === b
  );
}

// The one common deliberate use: null OR undefined in one check
function isMissing(v) {
  return v == null; // true for null and undefined only
}
console.log("isMissing(undefined/null/0/''):",
  isMissing(undefined), isMissing(null), isMissing(0), isMissing(""));

// Object.is is stricter than === for NaN and -0
console.log("Object.is(NaN, NaN):", Object.is(NaN, NaN));
console.log("0 === -0:", 0 === -0, "| Object.is(0, -0):", Object.is(0, -0));

// Exactly eight falsy values
const falsy = [false, 0, -0, 0n, "", null, undefined, NaN];
console.log("falsy count:", falsy.filter(function (v) { return !v; }).length, "of", falsy.length);

// Tricky truthy values
const truthy = ["0", "false", " ", [], {}, new Boolean(false), -1];
for (const v of truthy) {
  console.log(String(typeof v === "object" ? "object " + JSON.stringify(v) : JSON.stringify(v)).padEnd(16), "->", Boolean(v));
}

// Bug 1: testing emptiness with if (arr)
const arr = [];
console.log("if ([]) runs:", arr ? "yes" : "no", "| real check:", arr.length > 0);

// Bug 2: || throws away valid falsy values
const settings = { retries: 0, label: "" };
console.log("retries || 3:", settings.retries || 3);
console.log("retries ?? 3:", settings.retries ?? 3);
console.log("label || 'none':", JSON.stringify(settings.label || "none"));
console.log("label ?? 'none':", JSON.stringify(settings.label ?? "none"));

// !! is just Boolean()
console.log("!!'0' =", !!"0", "| !!0 =", !!0);

// Binary floats cannot store 0.1 or 0.2 exactly
console.log("0.1 + 0.2 =", 0.1 + 0.2);
console.log("equals 0.3?", 0.1 + 0.2 === 0.3);

// Compare with a tolerance
function almostEqual(a, b) {
  return Math.abs(a - b) < Number.EPSILON * Math.max(1, Math.abs(a), Math.abs(b)) * 4;
}
console.log("almostEqual:", almostEqual(0.1 + 0.2, 0.3));

// Money: sum prices as integer cents
const pricesFloat = [19.99, 5.01, 0.1, 0.2];
const pricesCents = [1999, 501, 10, 20];
const floatTotal = pricesFloat.reduce(function (s, p) { return s + p; }, 0);
const centsTotal = pricesCents.reduce(function (s, p) { return s + p; }, 0);
console.log("float total:", floatTotal);
console.log("cents total:", centsTotal);

// Format only at the edge
const fmt = new Intl.NumberFormat("en-US", { style: "currency", currency: "USD" });
console.log("formatted:", fmt.format(centsTotal / 100));

// Integers stay exact only up to 2^53 - 1
console.log("MAX_SAFE_INTEGER:", Number.MAX_SAFE_INTEGER);
console.log("2^53 === 2^53 + 1:", 2 ** 53 === 2 ** 53 + 1);

// Ways to create NaN
console.log("0 / 0 =", 0 / 0);
console.log("Math.sqrt(-1) =", Math.sqrt(-1));
console.log("Number('abc') =", Number("abc"));
console.log("undefined + 1 =", undefined + 1);

// NaN is the only value not equal to itself, and it spreads
console.log("NaN === NaN:", NaN === NaN);
console.log("NaN + 5 =", NaN + 5);

// Global isNaN coerces first; Number.isNaN does not
const inputs = ["hello", "42", undefined, NaN, {}];
for (const v of inputs) {
  console.log(
    String(typeof v === "object" ? "{}" : v).padEnd(9),
    "isNaN:", String(isNaN(v)).padEnd(5),
    "Number.isNaN:", Number.isNaN(v)
  );
}

// Other correct checks
const x = NaN;
console.log("Object.is(x, NaN):", Object.is(x, NaN));
console.log("x !== x:", x !== x);

// includes and indexOf disagree
console.log("[NaN].includes(NaN):", [NaN].includes(NaN));
console.log("[NaN].indexOf(NaN):", [NaN].indexOf(NaN));

// + concatenates if either primitive is a string, otherwise adds numbers
console.log("1 + 2 =", 1 + 2);
console.log("1 + 2 + '3' =", JSON.stringify(1 + 2 + "3"));   // left to right
console.log("'1' + 2 + 3 =", JSON.stringify("1" + 2 + 3));

// Objects are converted to primitives first
console.log("[] + [] =", JSON.stringify([] + []));
console.log("[1, 2] + 3 =", JSON.stringify([1, 2] + 3));
console.log("({}) + [] =", JSON.stringify({} + []));

// Other operators always use numbers
console.log("'5' - 2 =", "5" - 2);
console.log("'5' * '2' =", "5" * "2");
console.log("+'5' + 2 =", +"5" + 2);

// Custom conversion through Symbol.toPrimitive
const money = {
  [Symbol.toPrimitive](hint) {
    return hint === "number" ? 42 : "42 USD";
  },
};
console.log("money + '' =", money + "");
console.log("money * 2 =", money * 2);

// BigInt cannot be mixed with numbers
try {
  console.log(1n + 1);
} catch (e) {
  console.log("1n + 1 ->", e.name);
}

// || replaces every falsy value; ?? only null and undefined
const cfg = { port: 0, name: "", debug: false, host: null };
for (const key of ["port", "name", "debug", "host", "missing"]) {
  console.log(
    key.padEnd(8),
    "|| 'D':", JSON.stringify(cfg[key] || "D"),
    " ?? 'D':", JSON.stringify(cfg[key] ?? "D")
  );
}

// Short-circuit: the right side runs only when needed
let calls = 0;
function expensive() { calls++; return "computed"; }
const a = "have it" ?? expensive();
console.log("a =", a, "| expensive calls:", calls);

// Logical assignment (ES2021)
const o = { x: 0, y: 5, z: null };
o.x ||= 9;   // x was falsy -> assigned
o.y &&= 7;   // y was truthy -> assigned
o.z ??= 1;   // z was null -> assigned
console.log("after ||= &&= ??=:", o);

// Lazy cache
const cache = {};
function get(k) { return (cache[k] ??= expensive()); }
get("a"); get("a");
console.log("cache:", cache, "| expensive calls:", calls);

// Mixing needs parentheses: (a || b) ?? c
console.log((null || undefined) ?? "ok");

// Failure 1: return followed by a newline returns undefined
function bad() {
  return
  { ok: true };
}
function good() {
  return {
    ok: true,
  };
}
console.log("bad():", bad());
console.log("good():", good());

// Failure 2: a line starting with ( [ or a backtick joins the previous line
const src = "let a = 5\n[1, 2].length";
try {
  new Function(src)();
} catch (e) {
  console.log("glued lines ->", e.name);
}
console.log("same code with a semicolon:", new Function("let a = 5;\n return [1, 2].length")());

// Restricted production: no ++ after a line break
let a = 1, b = 1;
a
++b
console.log("a =", a, "b =", b);  // only b changed

// Safe style: always end statements, or start risky lines with ;
let list = [3, 1, 2]
;[4, 5].forEach(function (n) { list.push(n); })
console.log("list:", list);

const s = "😀";
console.log("length:", s.length);                 // 2 UTF-16 code units
console.log("first unit:", s[0].charCodeAt(0).toString(16));
console.log("code points:", [...s].length, "| codePointAt:", s.codePointAt(0).toString(16));

// Family emoji = 5 code points joined, shown as 1 character
const family = "\u{1F468}‍\u{1F469}‍\u{1F467}";
console.log("family length:", family.length);
console.log("family code points:", [...family].length);
const seg = new Intl.Segmenter("en", { granularity: "grapheme" });
console.log("family graphemes:", [...seg.segment(family)].length);

// Safe truncation by user-visible characters
function truncate(text, max) {
  const parts = [...seg.segment(text)].map(function (p) { return p.segment; });
  return parts.slice(0, max).join("");
}
const text = "ab" + family + "cd";
console.log("slice(0, 3):", JSON.stringify(text.slice(0, 3)));  // splits the emoji
console.log("truncate to 3:", truncate(text, 3) === "ab" + family);

// Normalisation: the same visible text can differ
const e1 = "é", e2 = "é";
console.log("e1 === e2:", e1 === e2, "| after NFC:", e1.normalize("NFC") === e2.normalize("NFC"));

// Lone surrogates
console.log("well formed?", "\uD800".isWellFormed(), "->", "\uD800".toWellFormed() === "�");

// typeof null: a historic bug kept for compatibility
console.log("typeof null:", typeof null);

// Sloppy mode silently makes implicit globals; strict mode throws
function sloppy() { oops = 1; }
function strict() { "use strict"; oops2 = 1; }
sloppy();
console.log("implicit global created:", typeof oops);
try {
  strict();
} catch (e) {
  console.log("strict mode ->", e.name);
}

// this inside a plain function
function who() { return this === undefined ? "undefined" : "global object"; }
function whoStrict() { "use strict"; return this === undefined ? "undefined" : "global object"; }
console.log("sloppy this:", who(), "| strict this:", whoStrict());

// Writing to a read-only property
const frozen = Object.freeze({ a: 1 });
frozen.a = 2;
console.log("sloppy write ignored:", frozen.a);
try {
  (function () { "use strict"; frozen.a = 2; })();
} catch (e) {
  console.log("strict write ->", e.name);
}

// Date months start at 0
console.log("new Date(2024, 0, 1) month:", new Date(2024, 0, 1).getMonth());

// Better modern alternatives exist beside the old behaviour
console.log("isNaN('x'):", isNaN("x"), "| Number.isNaN('x'):", Number.isNaN("x"));

// Bug 1: float sums
const items = [0.7, 0.1];
console.log("float sum:", items.reduce(function (a, b) { return a + b; }, 0));
const cents = items.map(function (p) { return Math.round(p * 100); });
const total = cents.reduce(function (a, b) { return a + b; }, 0);
console.log("cents sum:", total, "->", (total / 100).toFixed(2));

// Bug 2: a 64-bit id parsed as a JSON number loses digits
const json = '{"id": 1234567890123456789}';
console.log("parsed id:", JSON.parse(json).id);   // trailing digits are rounded off
console.log("safe?", Number.isSafeInteger(JSON.parse(json).id));

// Fix: send ids as strings
const fixed = JSON.parse('{"id": "1234567890123456789"}');
console.log("string id:", fixed.id);
console.log("as BigInt:", BigInt(fixed.id) + 1n);

// Rounding rule in integer space (half-up), e.g. 8.25% tax
function taxCents(amountCents, bps) {
  return Math.floor((amountCents * bps + 5000) / 10000);
}
console.log("tax on 1999 cents at 825 bps:", taxCents(1999, 825));

// Boundary test
console.log("2^53 + 1 collides:", 2 ** 53 === 2 ** 53 + 1);
